/* @lc app=leetcode id=2382 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun un(p: IntArray, s: LongArray, a: Int, b: Int) { find(p, a).let { x -> find(p, b).let { y -> if (x != y) p.set(x, y).also { s[y] += s[x] } } } } fun add(p: IntArray, s: LongArray, on: BooleanArray, nums: IntArray, q: Int): Long = true.also { on[q] = true }.also { s[q] = nums[q].toLong() }.also { if (q > 0 && on[q - 1]) un(p, s, q, q - 1) }.also { if (q < nums.size - 1 && on[q + 1]) un(p, s, q, q + 1) }.let { s[find(p, q)] } fun maximumSegmentSum(nums: IntArray, removeQueries: IntArray): LongArray = nums.size.let { n -> IntArray(n) { it }.let { p -> LongArray(n).let { s -> BooleanArray(n).let { on -> removeQueries.indices.reversed().fold(0L to ArrayList<Long>()) { (best, res), i -> maxOf(best, add(p, s, on, nums, removeQueries[i])).let { nb -> nb to res.also { it.add(best) } } }.second.reversed().toLongArray() } } } } }